library(creditratingsystem)
cases<-jsonlite::fromJSON('[{"candidates": [[-0.01, 10], [-1, 10]], "record": [1, 10], "model_variants": {"nominal": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}}, "scenarios": [{"scenario_id": "down", "model_variant_id": "nominal", "delta": [-0.1, 0.2], "weight": 1}, {"scenario_id": "up", "model_variant_id": "nominal", "delta": [0.1, 0.2], "weight": 1}], "feasibility_contract": {"contract_id": "c", "version": "1", "bounds": {"risk": [-10, 10], "fixed": [0, 20]}, "actionable_features": ["risk"], "immutable_features": ["fixed"], "integer_features": [], "one_hot_groups": [], "linear_constraints": [], "derived_relations": []}, "target": {"target_id": "t", "version": "1", "kind": "MODEL_OUTPUT", "operator": "<=", "value": 0}, "candidate_ids": ["thin", "robust"], "nominal_variant_id": "nominal"}, {"candidates": [[-0.01, 10], [-1, 10]], "record": [1, 10], "model_variants": {"nominal": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}, "broken": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}}, "scenarios": [{"scenario_id": "down", "model_variant_id": "nominal", "delta": [-0.1, 0.2], "weight": 1}, {"scenario_id": "up", "model_variant_id": "nominal", "delta": [0.1, 0.2], "weight": 1}, {"scenario_id": "failure", "model_variant_id": "broken", "delta": [0, 0], "weight": 2}], "feasibility_contract": {"contract_id": "c", "version": "1", "bounds": {"risk": [-10, 10], "fixed": [0, 20]}, "actionable_features": ["risk"], "immutable_features": ["fixed"], "integer_features": [], "one_hot_groups": [], "linear_constraints": [], "derived_relations": []}, "target": {"target_id": "t", "version": "1", "kind": "MODEL_OUTPUT", "operator": "<=", "value": 0}, "candidate_ids": ["thin", "robust"], "nominal_variant_id": "nominal"}, {"candidates": [[-0.01, 10], [-1, 10]], "record": [1, 10], "model_variants": {"nominal": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}}, "scenarios": [{"scenario_id": "outside", "model_variant_id": "nominal", "delta": [20, 0], "weight": 1}], "feasibility_contract": {"contract_id": "c", "version": "1", "bounds": {"risk": [-10, 10], "fixed": [0, 20]}, "actionable_features": ["risk"], "immutable_features": ["fixed"], "integer_features": [], "one_hot_groups": [], "linear_constraints": [], "derived_relations": []}, "target": {"target_id": "t", "version": "1", "kind": "MODEL_OUTPUT", "operator": "<=", "value": 0}, "candidate_ids": ["thin", "robust"], "nominal_variant_id": "nominal"}, {"candidates": [[-0.01, 11], [-1, 10]], "record": [1, 10], "model_variants": {"nominal": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}}, "scenarios": [{"scenario_id": "down", "model_variant_id": "nominal", "delta": [-0.1, 0.2], "weight": 1}, {"scenario_id": "up", "model_variant_id": "nominal", "delta": [0.1, 0.2], "weight": 1}], "feasibility_contract": {"contract_id": "c", "version": "1", "bounds": {"risk": [-10, 10], "fixed": [0, 20]}, "actionable_features": ["risk"], "immutable_features": ["fixed"], "integer_features": [], "one_hot_groups": [], "linear_constraints": [], "derived_relations": []}, "target": {"target_id": "t", "version": "1", "kind": "MODEL_OUTPUT", "operator": "<=", "value": 0}, "candidate_ids": ["invalid", "robust"], "nominal_variant_id": "nominal"}, {"candidates": [[-0.01, 10], [-1, 10]], "record": [1, 10], "model_variants": {"nominal": {"model_contract": {"model_id": "m", "model_version": "1", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}, "adverse": {"model_contract": {"model_id": "m", "model_version": "2", "feature_order": ["risk", "fixed"], "output_scale": "score", "deterministic_frozen": true, "target": {"event": "score", "horizon": 1, "time_unit": "years", "probability_measure": "PHYSICAL", "conditioning": "performing"}}}}, "scenarios": [{"scenario_id": "base", "model_variant_id": "nominal", "delta": [0, 0], "weight": 1}, {"scenario_id": "alternative", "model_variant_id": "adverse", "delta": [0, 0], "weight": 0}], "feasibility_contract": {"contract_id": "c", "version": "1", "bounds": {"risk": [-10, 10], "fixed": [0, 20]}, "actionable_features": ["risk"], "immutable_features": ["fixed"], "integer_features": [], "one_hot_groups": [], "linear_constraints": [], "derived_relations": []}, "target": {"target_id": "t", "version": "1", "kind": "MODEL_OUTPUT", "operator": "<=", "value": 0}, "candidate_ids": ["thin", "robust"], "nominal_variant_id": "nominal"}]',simplifyVector=FALSE);out<-list()
for(i in seq_along(cases)){
 a<-cases[[i]];a$record<-unlist(a$record)
 for(vid in names(a$model_variants))a$model_variants[[vid]]$predictor<-if(vid=='broken')function(z)stop('unavailable variant')else if(vid=='adverse')function(z)z[,1]+.2 else function(z)z[,1]
 r<-do.call(assess_counterfactual_robustness,a);out[[i]]<-list(value=r$value,diagnostics=r$diagnostics)
}
stopifnot(out[[1]]$value$candidate_summaries[[1]]$scenario_success_fraction==.5,out[[1]]$value$candidate_summaries[[2]]$all_scenarios_succeed,out[[2]]$value$candidate_summaries[[2]]$scenario_success_fraction==.5,out[[2]]$value$candidate_summaries[[2]]$unevaluable_weight==.5,out[[2]]$value$candidate_summaries[[2]]$scenario_feasibility_upper==1,is.null(out[[2]]$value$candidate_summaries[[2]]$worst_target_margin),out[[3]]$value$candidate_summaries[[1]]$scenario_feasibility_upper==0,out[[4]]$value$candidate_summaries[[1]]$scenario_feasibility_upper==0)
stopifnot(out[[5]]$value$candidate_summaries[[1]]$scenario_success_fraction==1,!out[[5]]$value$candidate_summaries[[1]]$all_scenarios_succeed,out[[5]]$value$candidate_summaries[[2]]$all_scenarios_succeed)
